head.script:
///////// 1. 변수 및 선언 영역 /////////

// 병합 샘플 데이터 — 시장 > 업종 > 규모 계층 + 분기 값. 병합 차이가 드러나도록 구성했다.
//  - 업종 '금융'(3·4행)·'IT'(5·6행), 규모 '중형'(2~4행)·'소형'(5·6행)은 시장 경계를 넘어 이어진다(bycol vs byrestriccol/bycolupper).
//  - 분기 값은 가로로 같은 값이 연속된다(byrow vs byrestricrow).
//  - '-' 와 빈 값은 mergeExcludeValue 예제용.
scwin.SAMPLE_ROWS = [
    { mktNm: "KOSPI",  sectNm: "제조",   gubun: "대형", q1: "100", q2: "100", q3: "120", q4: "130" },
    { mktNm: "KOSPI",  sectNm: "제조",   gubun: "중형", q1: "80",  q2: "90",  q3: "90",  q4: "90" },
    { mktNm: "KOSPI",  sectNm: "금융",   gubun: "중형", q1: "50",  q2: "55",  q3: "60",  q4: "60" },
    { mktNm: "KOSDAQ", sectNm: "금융",   gubun: "중형", q1: "40",  q2: "40",  q3: "40",  q4: "45" },
    { mktNm: "KOSDAQ", sectNm: "IT",     gubun: "소형", q1: "30",  q2: "35",  q3: "35",  q4: "35" },
    { mktNm: "KONEX",  sectNm: "IT",     gubun: "소형", q1: "-",   q2: "-",   q3: "-",   q4: "-" },
    { mktNm: "KONEX",  sectNm: "바이오", gubun: "",     q1: "",    q2: "12",  q3: "12",  q4: "-" },
    { mktNm: "KONEX",  sectNm: "바이오", gubun: "",     q1: "",    q2: "15",  q3: "18",  q4: "-" }
];

// 속성 요약표 데이터(구분 / 속성·메서드 / 값 / 설명)
scwin.PROP_ROWS = [
    { kind: "병합 방식", prop: "mergeCells", val: "never (기본값)", desc: "병합하지 않는다." },
    { kind: "병합 방식", prop: "mergeCells", val: "bycol", desc: "열(세로) 방향으로 같은 값이 연속된 셀을 병합한다. 고정 컬럼 영역은 제외." },
    { kind: "병합 방식", prop: "mergeCells", val: "byrestriccol", desc: "왼쪽 열들의 병합 경계 안에서만 열 방향 병합(계층형 데이터)." },
    { kind: "병합 방식", prop: "mergeCells", val: "bycolupper", desc: "body 컬럼 upperColumn 에 지정한 상위 컬럼 범위 안에서 열 방향 병합. 고정 컬럼도 포함." },
    { kind: "병합 방식", prop: "mergeCells", val: "byrow", desc: "행(가로) 방향으로 같은 값이 연속된 셀을 병합한다." },
    { kind: "병합 방식", prop: "mergeCells", val: "byrestricrow", desc: "위쪽 행들의 셀 경계를 넘지 않게 행 방향 병합." },
    { kind: "병합 방식", prop: "mergeCells", val: "bycolrec", desc: "bycol → byrow(기존 병합 유지) → 인접한 같은 값 병합 연결." },
    { kind: "병합 방식", prop: "mergeCells", val: "byrowrec", desc: "byrow → bycol(기존 병합 유지) → 인접한 같은 값 병합 연결." },
    { kind: "그리드 속성", prop: "mergeCol", val: "\"mktNm,sectNm\" 또는 \"0,1\"", desc: "병합 대상 컬럼을 한정한다(id 또는 index, 콤마 구분)." },
    { kind: "그리드 속성", prop: "mergeExcludeValue", val: "\"-,$blank\"", desc: "병합에서 제외할 값(콤마 구분). $blank 는 빈 문자열." },
    { kind: "그리드 속성", prop: "mergedCellVerticalAlign", val: "top / middle / bottom", desc: "병합 셀 텍스트의 세로 정렬." },
    { kind: "그리드 속성", prop: "mergeCellsFixedCols", val: "mergeCells 값과 동일", desc: "고정 컬럼(fixedColumn·fixedRightColumn) 영역의 병합 방식." },
    { kind: "그리드 속성", prop: "mergeCellsFixedRows", val: "mergeCells 값과 동일", desc: "고정 행(fixedRow) 영역의 병합 방식." },
    { kind: "그리드 속성", prop: "mergeCellsFixedColsFirst", val: "true / false (기본값)", desc: "고정 열·행 병합의 적용 순서. false 면 고정 행을 먼저 병합." },
    { kind: "그리드 속성", prop: "mergeRefreshAlways", val: "true (기본값) / false", desc: "그리드를 다시 그릴 때마다 병합 표시를 다시 적용한다." },
    { kind: "그리드 속성", prop: "oddEvenColorMerged", val: "true / false (기본값)", desc: "oddEvenColorDisplay 사용 시 병합 셀에도 홀짝 배경색을 적용." },
    { kind: "컬럼 속성", prop: "upperColumn", val: "상위 컬럼 id (콤마 구분)", desc: "mergeCells=bycolupper 일 때 이 컬럼을 상위 컬럼 범위 안에서만 병합." },
    { kind: "컬럼 속성", prop: "colMerge", val: "true / false (기본값)", desc: "mergeCells 와 별개인 컬럼 단위 표시 병합(위 행과 같은 값이면 숨김)." },
    { kind: "컬럼 속성", prop: "colMergeEdit", val: "true / false (기본값)", desc: "colMerge 컬럼 셀 편집 시 병합 표시를 다시 계산." },
    { kind: "API", prop: "mergeCells(type, opt)", val: "opt: mergeCol / mergeRow / upperColumn / noDraw", desc: "병합 방식을 적용·변경. opt.mergeCol 은 { 컬럼index: false } 형태로 이번 호출만 제외." },
    { kind: "API", prop: "mergeCol(col, bool)", val: "col: id 또는 index", desc: "컬럼을 병합 대상에서 제외(false)·포함(true). 다음 mergeCells 호출부터 반영." },
    { kind: "API", prop: "mergeRow(rowIndex, bool)", val: "rowIndex: 실제 행 index", desc: "행을 병합 대상에서 제외(false)·포함(true). 속성 mergeRow 는 엔진이 읽지 않음." },
    { kind: "API", prop: "mergeCell(obj)", val: "{ rowIndex, colIndex, rowSpan, colSpan }", desc: "임의 영역 병합(rowSpan·colSpan 1 이면 해제). 덮이는 셀에 시작 셀 값을 기록한다." },
    { kind: "API", prop: "mergeByFree / unmergeByFree", val: "(r1, c1, r2, c2) / (r, c)", desc: "좌표 범위로 병합·해제(mergeCell 래퍼)." },
    { kind: "API", prop: "mergeClear(opt)", val: "opt: { noDraw }", desc: "모든 병합 해제 + mergeCells·FixedCols·FixedRows 를 never 로 되돌림." },
    { kind: "API", prop: "getMerged(r, c)", val: "boolean", desc: "셀이 병합 영역에 속하는지 여부." },
    { kind: "API", prop: "getMergedInfo(r, c)", val: "{ merged, startRowIndex, startColIndex, endRowIndex, endColIndex }", desc: "셀이 속한 병합 영역의 범위." },
    { kind: "API", prop: "getMergedCells()", val: "{ \"행_열\": true }", desc: "병합 영역에 포함된 모든 셀 좌표." },
    { kind: "API", prop: "getMergeAll(cols, subtotal)", val: "JSON 문자열 [{ x, y, r, c }]", desc: "병합 목록(엑셀 출력 등에 사용)." }
];

// API 예제 기본 병합 방식
scwin.DEFAULT_MERGE_TYPE = "bycol";

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 로드 — 샘플 데이터를 dataList 에 적재한다(서버 무의존).
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        dltProps.setJSON(scwin.PROP_ROWS);
        dltMerge.setJSON(scwin.SAMPLE_ROWS);
        scwin.resetApiGrid();
    } catch (ex) {
        $c.exception.handleError(ex, { context: "GRIDVIEW_MERGECELLS.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 처리(없음).
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function () {};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name btnApplyType_onclick
 * @description 선택한 mergeCells 값을 API 로 적용한다 — grdApi.mergeCells(type).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btnApplyType_onclick = function (e) {
    try {
        const type = selMergeType.getValue() || scwin.DEFAULT_MERGE_TYPE;
        grdApi.mergeCells(type);
        scwin.showResult("mergeCells(\"" + type + "\") 적용");
    } catch (ex) {
        $c.exception.handleError(ex, { context: "GRIDVIEW_MERGECELLS.btnApplyType_onclick" });
    }
};

/**
 * @method
 * @name btnMergeCol_onclick
 * @description 시장·업종 컬럼만 병합 대상으로 지정한 뒤 다시 병합한다 — mergeCol(col, bool) + mergeCells.
 *  mergeCol 은 대상 표시만 바꾸므로 mergeCells 를 다시 호출해야 화면에 반영된다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btnMergeCol_onclick = function (e) {
    try {
        const targets = ["mktNm", "sectNm"];
        const colCnt = grdApi.getColumnCount();
        for (let i = 0; i < colCnt; i++) {
            grdApi.mergeCol(i, targets.indexOf(grdApi.getColumnID(i)) > -1);
        }
        const type = selMergeType.getValue() || scwin.DEFAULT_MERGE_TYPE;
        grdApi.mergeCells(type);
        scwin.showResult("mergeCol: " + targets.join(", ") + " 만 병합 → mergeCells(\"" + type + "\")");
    } catch (ex) {
        $c.exception.handleError(ex, { context: "GRIDVIEW_MERGECELLS.btnMergeCol_onclick" });
    }
};

/**
 * @method
 * @name btnMergeRow_onclick
 * @description 3행(index 2)을 병합 대상에서 제외한 뒤 다시 병합한다 — mergeRow(rowIndex, false) + mergeCells.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btnMergeRow_onclick = function (e) {
    try {
        grdApi.mergeRow(2, false);
        const type = selMergeType.getValue() || scwin.DEFAULT_MERGE_TYPE;
        grdApi.mergeCells(type);
        scwin.showResult("mergeRow(2, false): 3행 제외 → mergeCells(\"" + type + "\")");
    } catch (ex) {
        $c.exception.handleError(ex, { context: "GRIDVIEW_MERGECELLS.btnMergeRow_onclick" });
    }
};

/**
 * @method
 * @name btnMergeCell_onclick
 * @description 1행 1분기부터 2행×2열 영역을 임의 병합한다 — mergeCell({ rowIndex, colIndex, rowSpan, colSpan }).
 *  덮이는 셀(1행 2분기, 2행 1·2분기)에는 시작 셀 값이 기록되어 데이터가 바뀐다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btnMergeCell_onclick = function (e) {
    try {
        const colIndex = grdApi.getColumnIndex("q1");
        grdApi.mergeCell({ rowIndex: 0, colIndex: colIndex, rowSpan: 2, colSpan: 2 });
        scwin.showResult("mergeCell({ rowIndex: 0, colIndex: " + colIndex + ", rowSpan: 2, colSpan: 2 }) — 덮인 셀 값이 시작 셀 값으로 바뀜");
    } catch (ex) {
        $c.exception.handleError(ex, { context: "GRIDVIEW_MERGECELLS.btnMergeCell_onclick" });
    }
};

/**
 * @method
 * @name btnUnmerge_onclick
 * @description 1행 1분기 셀의 병합을 해제한다 — unmergeByFree(rowIndex, colIndex).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btnUnmerge_onclick = function (e) {
    try {
        const colIndex = grdApi.getColumnIndex("q1");
        grdApi.unmergeByFree(0, colIndex);
        scwin.showResult("unmergeByFree(0, " + colIndex + ")");
    } catch (ex) {
        $c.exception.handleError(ex, { context: "GRIDVIEW_MERGECELLS.btnUnmerge_onclick" });
    }
};

/**
 * @method
 * @name btnMergeClear_onclick
 * @description 모든 병합을 해제한다 — mergeClear(). mergeCells·mergeCellsFixedCols·mergeCellsFixedRows 도 never 가 된다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btnMergeClear_onclick = function (e) {
    try {
        grdApi.mergeClear();
        selMergeType.setValue("never");
        scwin.showResult("mergeClear() — 병합 전체 해제");
    } catch (ex) {
        $c.exception.handleError(ex, { context: "GRIDVIEW_MERGECELLS.btnMergeClear_onclick" });
    }
};

/**
 * @method
 * @name btnReset_onclick
 * @description API 예제 그리드를 초기 상태(원본 데이터 + bycol)로 되돌린다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btnReset_onclick = function (e) {
    try {
        scwin.resetApiGrid();
    } catch (ex) {
        $c.exception.handleError(ex, { context: "GRIDVIEW_MERGECELLS.btnReset_onclick" });
    }
};

/**
 * @method
 * @name grdApi_oncellclick
 * @description 셀 클릭 — getMerged / getMergedInfo 로 클릭한 셀의 병합 범위를 표시한다.
 * @param {Number} row 행 index
 * @param {Number} col 열 index
 * @param {String} colId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grdApi_oncellclick = function (row, col, colId) {
    try {
        const info = grdApi.getMergedInfo(row, col);
        if (!grdApi.getMerged(row, col)) {
            scwin.showResult("[" + row + ", " + col + "] " + colId + " — 병합되지 않은 셀");
            return;
        }
        scwin.showResult("[" + row + ", " + col + "] " + colId + " — 병합 범위: 행 " + info.startRowIndex + "~" + info.endRowIndex
            + ", 열 " + info.startColIndex + "~" + info.endColIndex);
    } catch (ex) {
        $c.exception.handleError(ex, { context: "GRIDVIEW_MERGECELLS.grdApi_oncellclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////

///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name resetApiGrid
 * @description API 예제 그리드의 병합 대상(mergeCol/mergeRow)과 데이터를 원복하고 기본 병합 방식을 다시 적용한다.
 * @returns {void}
 * @hidden N
 */
scwin.resetApiGrid = function () {
    const colCnt = grdApi.getColumnCount();
    for (let i = 0; i < colCnt; i++) {
        grdApi.mergeCol(i, true);
    }
    for (let r = 0; r < scwin.SAMPLE_ROWS.length; r++) {
        grdApi.mergeRow(r, true);
    }
    dltMergeApi.setJSON(JSON.parse(JSON.stringify(scwin.SAMPLE_ROWS)));   // mergeCell 이 데이터를 바꾸므로 사본 적재
    selMergeType.setValue(scwin.DEFAULT_MERGE_TYPE);
    grdApi.mergeCells(scwin.DEFAULT_MERGE_TYPE);
    scwin.showResult("초기화 — mergeCells(\"" + scwin.DEFAULT_MERGE_TYPE + "\"), 셀을 클릭하면 병합 정보를 표시합니다.");
};

/**
 * @method
 * @name showResult
 * @description API 실행 결과 문구를 표시한다.
 * @param {String} msg 표시 문구
 * @returns {void}
 * @hidden N
 */
scwin.showResult = function (msg) {
    txtApiResult.setValue(msg);
};
